import os, re

ROOT = "."
README = "README.md"
DOCS = sorted(["docs/" + f for f in os.listdir("docs") if f.endswith(".md")]) if os.path.isdir("docs") else []
SKILL = "src/lypning/assets/claude/skills/lypning"
OWNED = [README, "CLAUDE.md", "CHANGELOG.md"] + DOCS + sorted(
    ["src/lypning/assets/claude/skills/lypning/" + f for f in os.listdir(SKILL) if f.endswith(".md")]
    if os.path.isdir(SKILL) else []
) + ["src/lypning/assets/micropython/README.md"]

LEDGERS = {"BENCH-LEDGER.md", "HILLCLIMB.md", "PAPER.md", "RESEARCH.md", "CHANGELOG.md"}
P = re.compile(
    r"\btier [12]\b|\btier-[12]\b|\bmiddle tier\b|\bsecond tier\b|\bMicroPython tier\b|\bthree interpreters\b|\bthree tiers\b|\bboth tiers\b|\btwo subset tiers\b",
    re.I,
)

bad = {}
for d in OWNED:
    if os.path.basename(d) in LEDGERS:
        continue
    if not os.path.isfile(d):
        print("MISSING", d)
        continue
    with open(d, encoding="utf-8") as fh:
        text = fh.read()
    hits = [(n, l.strip()[:90]) for n, l in enumerate(text.splitlines(), 1) if P.search(l)]
    if hits:
        bad[str(d)] = hits

for k, v in bad.items():
    print(k, len(v))
    for n, l in v[:4]:
        print("   %d: %s" % (n, l))

print("TOTAL FILES FAILING:", len(bad), "of", len([d for d in OWNED if os.path.basename(d) not in LEDGERS]))
