import os, sys

# We cannot use glob, json, or collections.
# Use os.path functions to walk directories and files.
# Implement a minimal JSON parser sufficient for the subset of JSON lines we need:
#   - each line is a single JSON object (dictionary)
#   - keys are strings
#   - values can be: nested objects, arrays, strings, numbers, booleans, null
# We only need specific fields: "message" (an object with "model"), "isSidechain" (bool), etc.

def parse_json(s):
    s = s.strip()
    if not s:
        return None
    try:
        val, pos = _parse_value(s, 0)
        # ensure nothing left after trailing whitespace
        rest = s[pos:].strip()
        if rest:
            return None
        return val
    except Exception:
        return None

def _skip_ws(s, i):
    n = len(s)
    while i < n and s[i] in ' \t\r\n':
        i += 1
    return i

def _parse_string(s, i):
    # assume s[i]=='"'
    assert s[i] == '"'
    i += 1
    buf = []
    n = len(s)
    while i < n:
        c = s[i]
        if c == '\\':
            i += 1
            if i >= n: break
            c2 = s[i]
            if c2 == '"': buf.append('"')
            elif c2 == '\\': buf.append('\\')
            elif c2 == '/': buf.append('/')
            elif c2 == 'b': buf.append('\b')
            elif c2 == 'f': buf.append('\f')
            elif c2 == 'n': buf.append('\n')
            elif c2 == 'r': buf.append('\r')
            elif c2 == 't': buf.append('\t')
            elif c2 == 'u':
                hexs = s[i+1:i+5]
                if len(hexs) < 4: raise ValueError
                code = int(hexs, 16)
                buf.append(chr(code))
                i += 4
            else:
                buf.append(c2)
            i += 1
        elif c == '"':
            i += 1
            return ''.join(buf), i
        else:
            buf.append(c)
            i += 1
    raise ValueError('unterminated string')

def _parse_number(s, i):
    start = i
    n = len(s)
    if i < n and s[i] == '-':
        i += 1
    while i < n and s[i].isdigit():
        i += 1
    if i < n and s[i] == '.':
        i += 1
        while i < n and s[i].isdigit():
            i += 1
    if i < n and s[i] in 'eE':
        i += 1
        if i < n and s[i] in '+-':
            i += 1
        while i < n and s[i].isdigit():
            i += 1
    txt = s[start:i]
    if '.' in txt or 'e' in txt or 'E' in txt:
        return float(txt), i
    return int(txt), i

def _parse_value(s, i):
    i = _skip_ws(s, i)
    if i >= len(s):
        raise ValueError('unexpected end')
    c = s[i]
    if c == '{':
        return _parse_object(s, i)
    if c == '[':
        return _parse_array(s, i)
    if c == '"':
        return _parse_string(s, i)
    if c == 't':
        if s[i:i+4] == 'true':
            return True, i+4
        raise ValueError('bad literal')
    if c == 'f':
        if s[i:i+5] == 'false':
            return False, i+5
        raise ValueError('bad literal')
    if c == 'n':
        if s[i:i+4] == 'null':
            return None, i+4
        raise ValueError('bad literal')
    # number
    return _parse_number(s, i)

def _parse_object(s, i):
    assert s[i] == '{'
    i += 1
    obj = {}
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == '}':
        return obj, i+1
    while True:
        i = _skip_ws(s, i)
        key, i = _parse_string(s, i)
        i = _skip_ws(s, i)
        if i >= len(s) or s[i] != ':':
            raise ValueError('expected colon')
        i += 1
        val, i = _parse_value(s, i)
        obj[key] = val
        i = _skip_ws(s, i)
        if i >= len(s):
            raise ValueError('unexpected end in object')
        if s[i] == ',':
            i += 1
        elif s[i] == '}':
            i += 1
            return obj, i
        else:
            raise ValueError('expected , or }')

def _parse_array(s, i):
    assert s[i] == '['
    i += 1
    arr = []
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == ']':
        return arr, i+1
    while True:
        val, i = _parse_value(s, i)
        arr.append(val)
        i = _skip_ws(s, i)
        if i >= len(s):
            raise ValueError('unexpected end in array')
        if s[i] == ',':
            i += 1
        elif s[i] == ']':
            i += 1
            return arr, i
        else:
            raise ValueError('expected , or ]')


# Now replicate the original logic using os.listdir + os.path.isfile
home = os.path.expanduser("~")
root = home + "/.claude/projects"

per = {}   # basename -> {model_str: count}
side = {}  # model_str -> count
n = 0

# list direct subdirectories of root
try:
    dirs = os.listdir(root)
except OSError:
    dirs = []

for d in dirs:
    subdir = root + "/" + d
    if not os.path.isdir(subdir):
        continue
    try:
        files = os.listdir(subdir)
    except OSError:
        continue
    for fname in files:
        if not fname.endswith(".jsonl"):
            continue
        fpath = subdir + "/" + fname
        if not os.path.isfile(fpath):
            continue
        n += 1
        base = os.path.basename(fpath)
        try:
            fh = open(fpath)
        except OSError:
            continue
        with fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                ev = parse_json(line)
                if not isinstance(ev, dict):
                    continue
                m = ev.get("message")
                if isinstance(m, dict) and isinstance(m.get("model"), str):
                    model = m["model"]
                    # per[base][model] += 1
                    bd = per.get(base)
                    if bd is None:
                        per[base] = {}
                        bd = per[base]
                    bd[model] = bd.get(model, 0) + 1
                    if ev.get("isSidechain"):
                        side[model] = side.get(model, 0) + 1

print("transcript files scanned:", n)

multi = []
for k, v in per.items():
    real = [x for x in v if x != "<synthetic>"]
    if len(real) > 1:
        multi.append((k, dict(v)))

print("sessions with >1 real model:", len(multi), "of", len(per))
for k, v in multi[:10]:
