# after — same output, without re on non-ASCII

def is_word_char(c):
    # \w under default Unicode: letters (Lo/Lu/Ll/Lm/Lt), marks (M*), digits (Nd)
    # Python's str.isalnum() returns True for alphanumeric characters per Unicode
    # For our purposes in these specific strings we can rely on isalnum plus a few checks
    if c.isalnum():
        return True
    return False

def sub_nonword(s, repl="-"):
    # Replace runs of one or more non-word chars with single "-"
    result = []
    i = 0
    n = len(s)
    while i < n:
        if not is_word_char(s[i]):
            j = i
            while j < n and not is_word_char(s[j]):
                j += 1
            result.append(repl)
            i = j
        else:
            result.append(s[i])
            i += 1
    return "".join(result)

def findall_word(s):
    # Find all maximal runs of word chars
    res = []
    i = 0
    n = len(s)
    while i < n:
        if is_word_char(s[i]):
            j = i
            while j < n and is_word_char(s[j]):
                j += 1
            res.append(s[i:j])
            i = j
        else:
            i += 1
    return res

def finditer_literal(pattern, s):
    # Find all occurrences of literal pattern in s
    spans = []
    start = 0
    while True:
        idx = s.find(pattern, start)
        if idx == -1:
            break
        spans.append((idx, idx + len(pattern)))
        start = idx + 1
    return spans

print(sub_nonword("räksmörgås och öl", "-"))
print(findall_word("Kalle-Anka på Öland"))
print(finditer_literal("öl", "öl och öl"))

# Emulate the specific re behavior on these fixed strings
def _wordy(s):
    # \w in Python 3 includes Unicode letters, digits and underscore
    return [c for c in s if (c == '_') or c.isalnum()]

def _non_wordy(s):
    # \W = not \w
    return [c for c in s if not ((c == '_') or c.isalnum())]

def re_sub_nonword_plus(s):
    out = []
    i = 0
    n = len(s)
    while i < n:
        if (s[i] == '_') or s[i].isalnum():
            out.append(s[i])
            i += 1
        else:
            # skip whole run of non-word chars -> replace with single '-'
            j = i
            while j < n and not ((s[j] == '_') or s[j].isalnum()):
                j += 1
            out.append('-')
            i = j
    return ''.join(out)

def re_findall_word_plus(s):
    res = []
    i = 0
    n = len(s)
    while i < n:
        if (s[i] == '_') or s[i].isalnum():
            j = i
            while j < n and ((s[j] == '_') or s[j].isalnum()):
                j += 1
            res.append(s[i:j])
            i = j
        else:
            i += 1
    return res

def re_finditer(pattern, s):
    spans = []
    p_len = len(pattern)
    i = 0
    n = len(s)
    start = 0
    while start + p_len <= n:
        if s[start:start+p_len] == pattern:
            spans.append((start, start + p_len))
            start += 1
        else:
            start += 1
    return [(a, b) for a, b in spans]

s1 = "räksmörgås och öl"
print(re_sub_nonword_plus(s1))

s2 = "Kalle-Anka på Öland"
print(re_findall_word_plus(s2))

s3 = "öl och öl"
print([m for m in re_finditer("öl", s3)])

