def _match(s, si, p, pi):
    while pi < len(p):
        c = p[pi]
        if c == '*':
            if pi + 1 < len(p) and p[pi + 1] == '?':
                nq = 1
                j = pi + 2
                while j < len(p) and p[j] == '?':
                    nq += 1
                    j += 1
                k = len(s) - si - nq
                if k < 0:
                    return False
                if _match(s, si + k, p, j):
                    return True
                return False
            else:
                for skip in range(len(s) - si + 1):
                    if _match(s, si + skip, p, pi + 1):
                        return True
                return False
        elif c == '?' :
            if si >= len(s):
                return False
            si += 1
            pi += 1
        elif c == '[':
            if si >= len(s):
                return False
            j = pi + 1
            negate = False
            if j < len(p) and p[j] == '!':
                negate = True
                j += 1
            # Find closing bracket
            found_close = False
            close_idx = -1
            t = j
            while t < len(p):
                if p[t] == ']':
                    # Check if this is a literal ']' (only if it's the first char after [ or [!)
                    if t > j or (t == j and j == pi + 1):
                        found_close = True
                        close_idx = t
                        break
                    t += 1
                    continue
                # If we haven't seen any element yet and t==j, then ] could be literal
                # Actually standard behavior: ] immediately after [ or [! is literal
                if t == j:
                    pass
                t += 1
            # Proper logic for finding close bracket
            close_idx = -1
            t = j
            elements_start = t
            while t < len(p):
                ch = p[t]
                if ch == ']':
                    if t == elements_start:
                        # Literal ] as first character
                        t += 1
                        continue
                    else:
                        close_idx = t
                        break
                t += 1

            if close_idx == -1:
                # No closing bracket, treat [ as literal
                if s[si] != '[':
                    return False
                si += 1
                pi += 1
            else:
                body = p[elements_start:close_idx] if elements_start <= close_idx else ""
                # Wait, need to handle the case where ] is first char literally
                # Let me redo this more carefully
                # The bracket expression starts at j (after optional !)
                # Scan for unescaped ]
                body_chars = []
                t = j
                body_end = -1
                first_char_processed = False
                while t < len(p):
                    ch = p[t]
                    if ch == ']':
                        if not first_char_processed:
                            # This ] is literal (it's the first char in the set)
                            body_chars.append(']')
                            first_char_processed = True
                            t += 1
                            continue
                        else:
                            body_end = t
                            break
                    body_chars.append(ch)
                    first_char_processed = True
                    t += 1

                if body_end == -1:
                    # No closing bracket, treat [ as literal
                    if s[si] != '[':
